def put(module,address,purpose,details,inputs='',outputs='',effects='',confidence='proven'):
    notes[f'O{module:02d}:{address:04X}']=dict(purpose=purpose,details=details,
        inputs=inputs,outputs=outputs,effects=effects,confidence=confidence,
        validation='статический разбор исходных байтов, сборка и запуск игры не выполнялись')

